window.SLIDE_DECKS["banco-de-dados/aula-01"] = {
  title: "Fundamentos e modelagem conceitual",
  slides: [
  "<section class=\"slide slide-cover active\">\n      <div class=\"section-tag\">Apresentação da Disciplina &bull; Aula 01</div>\n      <h1 class=\"cover-title\">BANCO DE DADOS I</h1>\n      <p class=\"slide-subtitle\" style=\"font-size: 1.25rem; max-width: 800px; margin-bottom: 25px;\">\n        Fundamentos de Persistência, Níveis de Abstração de Dados e Metodologia de Modelagem Conceitual\n      </p>\n\n      <div style=\"display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-bottom: 30px;\">\n        <span class=\"badge badge-red\">Fatec Sorocaba</span>\n        <span class=\"badge badge-gray\">CST em Análise e Desenvolvimento de Sistemas</span>\n        <span class=\"badge badge-gray\">1º Semestre &bull; Matriz R-11</span>\n        <span class=\"badge badge-blue\">Prof. André Souza</span>\n        <span class=\"badge badge-green\">Aula remota pelo Teams</span>\n      </div>\n\n      <div class=\"callout\" style=\"max-width: 760px; text-align: left;\">\n        <strong>Dinâmica de hoje:</strong> 1 hora de fundamentos, 40 minutos de fixação, 1 hora de correção e modelagem\n        conceitual, e 40 minutos para iniciar a atividade que será corrigida na próxima aula presencial.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Organização do encontro &bull; 3h20</div>\n      <h2 class=\"slide-title\">Roteiro da Aula 01</h2>\n      <p class=\"slide-subtitle\">Dois blocos de explicação, cada um seguido por 40 minutos de prática.</p>\n\n      <div class=\"stepper\">\n        <div class=\"step-item\">\n          <div class=\"step-circle\">1</div>\n          <div class=\"step-title\">Fundamentos</div>\n          <div class=\"step-desc\">60 min de conceitos</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">2</div>\n          <div class=\"step-title\">Fixação 1</div>\n          <div class=\"step-desc\">40 min, entrega no Teams</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">3</div>\n          <div class=\"step-title\">Correção e modelagem</div>\n          <div class=\"step-desc\">60 min</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">4</div>\n          <div class=\"step-title\">Fixação 2</div>\n          <div class=\"step-desc\">40 min, correção presencial</div>\n        </div>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 24px;\">\n        <strong>Durante as atividades:</strong> permaneça na reunião, registre as respostas no caderno e envie dúvidas\n        pelo chat. Identifique a entrega com nome e turma.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Bloco 1 &bull; Situação de abertura</div>\n      <h2 class=\"slide-title\">O crescimento da Loja Conecta</h2>\n      <p class=\"slide-subtitle\">Uma pequena loja começou com uma planilha. Depois das vendas pela internet, o mesmo método passou a causar atrasos, divergências e retrabalho.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Como a operação funciona hoje</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.9rem; line-height: 1.75; padding-left: 18px;\">\n            <li>Vendas registra clientes e pedidos em uma planilha.</li>\n            <li>O estoque mantém outro arquivo com produtos e quantidades.</li>\n            <li>O financeiro copia os pedidos para controlar pagamentos.</li>\n            <li>O atendimento consulta conversas e anotações separadas.</li>\n          </ul>\n        </div>\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Problemas percebidos</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.9rem; line-height: 1.75; padding-left: 18px;\">\n            <li>O endereço do mesmo cliente aparece de formas diferentes.</li>\n            <li>Dois vendedores podem reservar a última unidade do produto.</li>\n            <li>Alguns pagamentos não ficam associados ao pedido correto.</li>\n            <li>Preparar o relatório mensal exige reunir vários arquivos.</li>\n          </ul>\n        </div>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 18px;\">\n        <strong>Pergunta para a turma:</strong> qual desses problemas parece mais grave? Durante o bloco, veremos como dados, metadados, SGBD e níveis de abstração ajudam a organizar essa operação.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Introdução</div>\n      <h2 class=\"slide-title\">Papel dos Bancos de Dados em Sistemas de Informação</h2>\n      <p class=\"slide-subtitle\">Quando uma compra é paga, o aplicativo pode fechar, mas o pedido, o estoque e o pagamento precisam continuar registrados e consistentes.</p>\n\n      <div class=\"grid-3\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Persistência e Confiabilidade</div>\n          <p class=\"card-desc\">Garantia de que os dados transacionais permanecem íntegros após o encerramento dos\n            processos da aplicação ou eventuais falhas do sistema operacional.</p>\n        </div>\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Desempenho e Eficiência</div>\n          <p class=\"card-desc\">Otimização de recuperação de dados em grandes volumes por meio de indexação, paginação de\n            memória e planos estruturados de execução de consultas.</p>\n        </div>\n        <div class=\"card card-green\">\n          <div class=\"card-title\">Integridade Centralizada</div>\n          <p class=\"card-desc\">Aplicação de restrições semânticas e referenciais no próprio repositório, garantindo que\n            nenhum cliente ou serviço grave informações inconsistentes.</p>\n        </div>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 20px;\">\n        <strong>Na Loja Conecta:</strong> o banco precisa registrar o pedido mesmo que o navegador feche, impedir a\n        venda de estoque inexistente e manter o pagamento associado ao cliente correto.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Plano de Ensino &bull; Ementa</div>\n      <h2 class=\"slide-title\">Ementa Regimental (PPC — Matriz R-11)</h2>\n      <p class=\"slide-subtitle\">Ao longo do semestre, partiremos de uma necessidade real, como controlar pedidos de uma loja, até chegar às tabelas e consultas que sustentam o sistema.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Conteúdo Programático</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.9rem; line-height: 1.7; padding-left: 18px;\">\n            <li>Conceitos fundamentais de Bancos de Dados e SGBD.</li>\n            <li>Modelagem de dados: Abordagem Entidade-Relacionamento (ER).</li>\n            <li>Fases de projeto: Modelos Conceitual, Lógico/Relacional e Físico.</li>\n            <li>Teoria da Normalização de Dados (1FN, 2FN e 3FN).</li>\n            <li>Restrições de integridade referencial e de domínio.</li>\n            <li>Linguagem SQL: Definição (DDL), Manipulação (DML) e Consulta (DQL).</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Competências Profissionais</div>\n          <div style=\"margin-bottom: 12px;\">\n            <strong style=\"color: var(--cps-gray-dark);\">1. Planejamento e Modelagem de Dados:</strong>\n            <p class=\"card-desc\">Capacidade de analisar requisitos de software e conceber esquemas conceituais e lógicos\n              normalizados que atendam às regras de negócio.</p>\n          </div>\n          <div>\n            <strong style=\"color: var(--cps-gray-dark);\">2. Implementação e Operação com SGBD:</strong>\n            <p class=\"card-desc\">Capacidade de criar e manter estruturas de tabelas, aplicar restrições de integridade e\n              construir consultas SQL eficientes.</p>\n          </div>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Plano de Ensino &bull; Objetivos</div>\n      <h2 class=\"slide-title\">Objetivos de Aprendizagem do Semestre</h2>\n      <p class=\"slide-subtitle\">O objetivo é conseguir ouvir uma regra como “cada pedido pertence a um cliente” e transformá-la em um banco íntegro e consultável.</p>\n\n      <div class=\"grid-4\">\n        <div class=\"card\">\n          <div class=\"badge badge-red\" style=\"margin-bottom: 8px;\">01. Abstração</div>\n          <div class=\"card-title\" style=\"font-size: 0.95rem;\">Modelagem Conceitual</div>\n          <p class=\"card-desc\">Interpretar requisitos de negócio em linguagem natural e construir Diagramas\n            Entidade-Relacionamento (DER).</p>\n        </div>\n        <div class=\"card\">\n          <div class=\"badge badge-blue\" style=\"margin-bottom: 8px;\">02. Mapeamento</div>\n          <div class=\"card-title\" style=\"font-size: 0.95rem;\">Projeto Lógico</div>\n          <p class=\"card-desc\">Mapear o DER para o Modelo Relacional, determinando chaves primárias (PK), chaves\n            estrangeiras (FK) e regras de integridade.</p>\n        </div>\n        <div class=\"card\">\n          <div class=\"badge badge-green\" style=\"margin-bottom: 8px;\">03. Otimização</div>\n          <div class=\"card-title\" style=\"font-size: 0.95rem;\">Normalização</div>\n          <p class=\"card-desc\">Aplicar a 1ª, 2ª e 3ª Formas Normais para eliminar redundâncias e evitar anomalias de\n            atualização e exclusão.</p>\n        </div>\n        <div class=\"card\">\n          <div class=\"badge badge-gray\" style=\"margin-bottom: 8px;\">04. Implementação</div>\n          <div class=\"card-title\" style=\"font-size: 0.95rem;\">Linguagem SQL</div>\n          <p class=\"card-desc\">Desenvolver scripts DDL para criação de tabelas e consultas DQL complexas com filtros,\n            ordenação e junções (JOINs).</p>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Plano de Ensino &bull; Avaliação</div>\n      <h2 class=\"slide-title\">Critérios de Avaliação e Composição da Média</h2>\n      <p class=\"slide-subtitle\">Como em um projeto profissional, a aprendizagem será observada nas entregas intermediárias e na capacidade de construir uma solução completa.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Fórmula da Média Final (MF)</div>\n          <div class=\"code-box\" style=\"margin: 10px 0; text-align: center; font-weight: 600;\">\n            MF = (Média dos Exercícios × 0,5) + (Prova Prática Final × 0,5)\n          </div>\n          <p class=\"card-desc\"><strong>50% — Atividades Práticas Contínuas:</strong> Exercícios em sala, entregas de\n            modelagem e resolução de oficinas práticas.</p>\n          <p class=\"card-desc\" style=\"margin-top: 6px;\"><strong>50% — Prova Prática Final:</strong> Avaliação presencial\n            individual em laboratório cobrindo modelagem relacional, normalização e consultas SQL.</p>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Datas Regimentais e Condições</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.9rem; line-height: 1.9; padding-left: 18px;\">\n            <li><strong>Entregas Contínuas:</strong> Ao longo do semestre letivo.</li>\n            <li><strong style=\"color: var(--cps-red);\">Prova Prática Final:</strong> <strong>27/11/2026</strong>.</li>\n            <li><strong style=\"color: var(--tech-amber);\">Prova de Recuperação:</strong> <strong>04/12/2026</strong>.\n            </li>\n            <li><strong>Critérios de Aprovação:</strong> Média Final &ge; 6,0 e Frequência Regimental &ge; 75%.</li>\n          </ul>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Plano de Ensino &bull; Cronograma</div>\n      <h2 class=\"slide-title\">Cronograma Estruturado em 4 Blocos</h2>\n      <p class=\"slide-subtitle\">Seguiremos o caminho usado em projetos reais: compreender o negócio, modelar, organizar as tabelas e implementar a solução em SQL.</p>\n\n      <div class=\"grid-4\">\n        <div class=\"card card-red\">\n          <div class=\"badge badge-red\">Bloco 1 &bull; Aulas 1 a 3</div>\n          <div class=\"card-title\" style=\"margin-top: 8px; font-size: 0.95rem;\">Fundamentos &amp; Modelagem Conceitual\n          </div>\n          <p class=\"card-desc\">ANSI/SPARC, ciclo de vida, MER vs. DER, entidades, atributos, cardinalidades e\n            especializações.</p>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"badge badge-blue\">Bloco 2 &bull; Aula 4 + Oficinas</div>\n          <div class=\"card-title\" style=\"margin-top: 8px; font-size: 0.95rem;\">Mapeamento Lógico Relacional</div>\n          <p class=\"card-desc\">Regras de conversão de DER para tabelas relacionais, integridade referencial (PK e FK).\n          </p>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"badge badge-green\">Bloco 3 &bull; Aula 5</div>\n          <div class=\"card-title\" style=\"margin-top: 8px; font-size: 0.95rem;\">Teoria da Normalização</div>\n          <p class=\"card-desc\">Dependências funcionais e decomposição relacional nas três primeiras formas normais (1FN,\n            2FN, 3FN).</p>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"badge badge-gray\">Bloco 4 &bull; Aulas 6 a 10</div>\n          <div class=\"card-title\" style=\"margin-top: 8px; font-size: 0.95rem;\">Implementação SQL</div>\n          <p class=\"card-desc\">Criação de estruturas (DDL), manutenção de dados (DML) e consultas analíticas com junções\n            (DQL/JOINs).</p>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Plano de Ensino &bull; Bibliografia</div>\n      <h2 class=\"slide-title\">Bibliografia Básica e Complementar</h2>\n      <p class=\"slide-subtitle\">Referências bibliográficas alinhadas ao plano de curso.</p>\n\n      <div class=\"grid-3\">\n        <div class=\"card\">\n          <div class=\"card-title\" style=\"color: var(--cps-red);\">ELMASRI &amp; NAVATHE</div>\n          <p style=\"font-size: 0.85rem; font-weight: 700; color: var(--cps-gray-dark);\">Sistemas de Banco de Dados</p>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 6px;\">7ª Edição, Pearson, 2019.<br>Referência\n            principal para arquitetura de sistemas, modelos conceituais e teoria relacional.</p>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-title\" style=\"color: var(--tech-blue);\">SILBERSCHATZ et al.</div>\n          <p style=\"font-size: 0.85rem; font-weight: 700; color: var(--cps-gray-dark);\">Sistema de Banco de Dados</p>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 6px;\">7ª Edição, GEN LTC, 2020.<br>Enfoque em\n            processamento interno, indexação física e controle transacional.</p>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-title\" style=\"color: var(--tech-green);\">MARTELLI et al.</div>\n          <p style=\"font-size: 0.85rem; font-weight: 700; color: var(--cps-gray-dark);\">Modelagem e Banco de Dados</p>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 6px;\">2ª Edição, Senac, 2018.<br>Referência\n            didática para práticas de modelagem conceitual e lógica em ferramentas gráficas.</p>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica</div>\n      <h2 class=\"slide-title\">Dado, Informação, Conhecimento e Metadado</h2>\n      <p class=\"slide-subtitle\">Na Loja Conecta, <code>450,00</code> isolado é apenas um dado; associado ao pedido PED-1024, passa a informar o valor de uma venda real.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">1. Dado (<em>Data</em>)</div>\n          <p class=\"card-desc\">Elemento atômico bruto, sem contexto semântico intrínseco. Não permite interpretação\n            isolada.</p>\n          <p class=\"card-desc\" style=\"margin-top: 4px;\"><strong>Exemplo:</strong> <code>450.00</code>,\n            <code>'PED-1024'</code>.\n          </p>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">2. Informação (<em>Information</em>)</div>\n          <p class=\"card-desc\">Dado processado, estruturado e dotado de contexto semântico compreensível.</p>\n          <p class=\"card-desc\" style=\"margin-top: 4px;\"><strong>Exemplo:</strong> <em>\"O pedido PED-1024, realizado por\n              Ana, totalizou R$ 450,00 e aguarda pagamento.\"</em></p>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"card-title\">3. Conhecimento (<em>Knowledge</em>)</div>\n          <p class=\"card-desc\">Padrões e correlações identificados a partir de conjuntos de informações para fundamentar\n            tomadas de decisão.</p>\n          <p class=\"card-desc\" style=\"margin-top: 4px;\"><strong>Exemplo:</strong> perceber que pedidos pagos no mesmo\n            dia têm menos cancelamentos e priorizar sua separação.</p>\n        </div>\n\n        <div class=\"card card-amber\">\n          <div class=\"card-title\">4. Metadado (<em>Metadata</em>)</div>\n          <p class=\"card-desc\">Dados que descrevem a estrutura, restrições e tipos dos dados armazenados (catálogo do\n            sistema).</p>\n          <p class=\"card-desc\" style=\"margin-top: 4px;\"><strong>Exemplo:</strong> o campo <code>valor_total</code> usa\n            <code>NUMERIC(10,2)</code> e não aceita valores negativos.</p>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Infográfico Estrutural</div>\n      <h2 class=\"slide-title\">Pirâmide de Informação e Sustentação por Metadados</h2>\n      <p class=\"slide-subtitle\">A Loja Conecta registra cada item vendido, calcula o faturamento diário e usa o histórico para decidir quais produtos precisam de reposição.</p>\n\n      <div class=\"diagram-container\">\n        <img src=\"../Banco de Dados I/slides/img/piramide_dados.png\" alt=\"Pirâmide de Dados, Informação e Conhecimento com Metadados\" class=\"diagram-img\">\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Tipologia dos Dados</div>\n      <h2 class=\"slide-title\">Classificação dos Dados: Estruturados, Semiestruturados e Não Estruturados</h2>\n      <p class=\"slide-subtitle\">A Loja Conecta combina pedidos em tabelas, respostas JSON do frete e fotos dos produtos; cada formato possui estrutura e uso diferentes.</p>\n\n      <div class=\"grid-3\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">1. Dados Estruturados</div>\n          <p class=\"card-desc\">Organizados em formato rígido e predeterminado, com esquema estrito de tabelas, linhas e colunas (<em>Schema-on-Write</em>).</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.82rem; line-height: 1.6; padding-left: 16px; margin-top: 10px;\">\n            <li><strong>Formato:</strong> Tabelas relacionais, tipos atômicos (inteiros, decimais, datas).</li>\n            <li><strong>Recuperação:</strong> Consultas diretas e previsíveis via SQL.</li>\n            <li><strong>Exemplos:</strong> Bancos relacionais (PostgreSQL, MySQL), planilhas estritas, arquivos CNAB bancários.</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-amber\">\n          <div class=\"card-title\">2. Dados Semiestruturados</div>\n          <p class=\"card-desc\">Não seguem um esquema tabular rígido, mas contêm marcadores, tags ou hierarquias internas que definem elementos (<em>Schema-on-Read</em>).</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.82rem; line-height: 1.6; padding-left: 16px; margin-top: 10px;\">\n            <li><strong>Formato:</strong> Pares chave-valor, matrizes aninhadas e árvores hierárquicas.</li>\n            <li><strong>Recuperação:</strong> Exige analisadores sintáticos (<em>parsers</em>) ou bancos orientados a documentos.</li>\n            <li><strong>Exemplos:</strong> Arquivos JSON, XML, YAML, feeds RSS, documentos NoSQL (MongoDB).</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">3. Dados Não Estruturados</div>\n          <p class=\"card-desc\">Não possuem estrutura interna ou modelo conceitual identificável para consultas relacionais convencionais.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.82rem; line-height: 1.6; padding-left: 16px; margin-top: 10px;\">\n            <li><strong>Volume:</strong> Representam mais de 80% do volume global de dados gerados no mundo corporativo.</li>\n            <li><strong>Recuperação:</strong> Exige processamento de linguagem natural (NLP), visão computacional ou indexação textual.</li>\n            <li><strong>Exemplos:</strong> Imagens, áudios, vídeos, relatórios PDF, e-mails, posts de redes sociais.</li>\n          </ul>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Paradigmas de Persistência</div>\n      <h2 class=\"slide-title\">Bancos Relacionais (SQL) vs. Não Relacionais (NoSQL)</h2>\n      <p class=\"slide-subtitle\">Na Loja Conecta, pedidos e pagamentos pedem consistência relacional; o catálogo de fornecedores pode conter atributos muito variados.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Bancos Relacionais (RDBMS / SQL)</div>\n          <p class=\"card-desc\">Fundamentados no modelo relacional proposto por Edgar F. Codd (1970). Estrutura tabular estrita e forte base matemática.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.84rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li><strong>Estrutura Central:</strong> Tabelas (relações), colunas (atributos) e linhas (tuplas).</li>\n            <li><strong>Integridade Referencial:</strong> Chaves Primárias (PK) e Estrangeiras (FK).</li>\n            <li><strong>Transações ACID:</strong> Atomicidade, Consistência, Isolamento e Durabilidade estritas.</li>\n            <li><strong>Linguagem:</strong> SQL padronizado (ANSI/ISO).</li>\n            <li><strong>Sistemas:</strong> PostgreSQL, MySQL, Oracle Database, Microsoft SQL Server, SQLite.</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"card-title\">Bancos Não Relacionais (NoSQL)</div>\n          <p class=\"card-desc\">Projetados para escalabilidade horizontal massiva, modelos de dados heterogêneos e esquemas dinâmicos flexíveis.</p>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.84rem; line-height: 1.6; padding-left: 16px; margin-top: 8px;\">\n            <li><strong>Orientados a Documentos:</strong> JSON/BSON flexível (ex.: MongoDB, CouchDB).</li>\n            <li><strong>Chave-Valor:</strong> Altíssima velocidade em memória (ex.: Redis, Memcached).</li>\n            <li><strong>Família de Colunas:</strong> Escrita analítica massiva (ex.: Apache Cassandra, ScyllaDB).</li>\n            <li><strong>Grafos:</strong> Foco em nós e relacionamentos densos (ex.: Neo4j, Amazon Neptune).</li>\n            <li><strong>Filosofia:</strong> Modelo BASE e Teorema CAP (alta disponibilidade e tolerância a partições).</li>\n          </ul>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Engenharia de Decisão</div>\n      <h2 class=\"slide-title\">Quando Usar Cada Paradigma & O Foco da Disciplina</h2>\n      <p class=\"slide-subtitle\">A loja pode usar SQL para clientes, pedidos e pagamentos, reservando uma estrutura flexível para descrições variáveis do catálogo.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Quando Adotar Banco Relacional?</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.84rem; line-height: 1.6; padding-left: 16px;\">\n            <li><strong>Transações Críticas:</strong> Sistemas financeiros, contábeis, controle de estoque e ERPs onde a consistência é mandatória (ACID).</li>\n            <li><strong>Relações Complexas:</strong> Entidades altamente interligadas exigindo cruzamento de dados com integridade referencial e <em>JOINs</em>.</li>\n            <li><strong>Consultas Ad-Hoc:</strong> Necessidade de extrair relatórios gerenciais e filtros analíticos inéditos e dinâmicos via SQL.</li>\n            <li><strong>Esquema Estável:</strong> Regras de negócio bem delimitadas com ciclo de vida estruturado.</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-amber\">\n          <div class=\"card-title\">Quando Adotar NoSQL?</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.84rem; line-height: 1.6; padding-left: 16px;\">\n            <li><strong>Escalabilidade Horizontal Extrema:</strong> Volume e vazão de gravação distribuída que superam os limites verticais de um servidor.</li>\n            <li><strong>Esquemas Dinâmicos e Mutáveis:</strong> Registros onde cada entidade possui atributos totalmente distintos (ex.: catálogo heterogêneo de marketplace).</li>\n            <li><strong>Operações Simples de Baixa Latência:</strong> Acesso direto por chave para leitura em microssegundos (ex.: sessões de usuários, cache).</li>\n            <li><strong>Redes Complexas:</strong> Análise de conexões sociais e caminhos mínimos (bancos de grafos).</li>\n          </ul>\n        </div>\n      </div>\n\n      <div class=\"card card-red\" style=\"margin-top: 15px;\">\n        <div class=\"card-title\" style=\"color: var(--cps-red);\">O Foco do Componente: Banco de Dados I</div>\n        <p class=\"card-desc\" style=\"font-size: 0.88rem; line-height: 1.6;\">\n          Neste semestre, o nosso foco aprofundado é o <strong>Modelo Relacional</strong>. Ele constitui o alicerce de mais de 70% dos sistemas corporativos em produção no mundo. O domínio da modelagem conceitual, das regras de integridade, da normalização e da linguagem SQL é o <strong>fundamento técnico universal e indispensável</strong> para qualquer profissional de tecnologia antes de avançar para arquiteturas poliglota ou ecossistemas NoSQL.\n        </p>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica</div>\n      <h2 class=\"slide-title\">Sistemas de Arquivos Convencionais vs. SGBD</h2>\n      <p class=\"slide-subtitle\">Na Loja Conecta, vendas e financeiro mantêm cópias separadas dos clientes; uma alteração de endereço raramente chega a todos os arquivos.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Sistemas de Arquivos (<em>File-System</em>)</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.88rem; line-height: 1.7; padding-left: 18px;\">\n            <li><strong>Redundância descontrolada:</strong> Múltiplas cópias do mesmo dado gerando inconsistências.</li>\n            <li><strong>Acoplamento Programa-Dados:</strong> Modificações no formato do arquivo exigem alteração no\n              código-fonte de todos os programas associados.</li>\n            <li><strong>Dificuldade de concorrência:</strong> Ausência de controle transacional para acessos e gravações\n              simultâneas.</li>\n            <li><strong>Integridade dispersa:</strong> Regras de validação implementadas isoladamente em cada aplicação.\n            </li>\n          </ul>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"card-title\">Sistemas Gerenciadores de Bancos de Dados (SGBD)</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.88rem; line-height: 1.7; padding-left: 18px;\">\n            <li><strong>Redundância controlada:</strong> Unificação dos dados e controle centralizado.</li>\n            <li><strong>Independência de dados:</strong> Esquemas lógicos desacoplados da representação física.</li>\n            <li><strong>Controle de concorrência e transações:</strong> Garantia das propriedades ACID (Atomicidade,\n              Consistência, Isolamento e Durabilidade).</li>\n            <li><strong>Catálogo de metadados:</strong> Estrutura de dados autodescritiva gerenciada internamente.</li>\n          </ul>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Infográfico Estrutural</div>\n      <h2 class=\"slide-title\">Arquitetura ANSI/SPARC em Três Níveis</h2>\n      <p class=\"slide-subtitle\">O atendente da loja vê nome e pedido, o analista vê tabelas relacionadas e o servidor cuida de arquivos e índices: três visões do mesmo banco.</p>\n\n      <div class=\"diagram-container\">\n        <svg class=\"diagram-svg\" viewBox=\"0 0 880 340\" xmlns=\"http://www.w3.org/2000/svg\">\n          <!-- Nível Externo -->\n          <rect x=\"40\" y=\"15\" width=\"800\" height=\"70\" rx=\"4\" fill=\"#f8fafc\" stroke=\"#0284c7\" stroke-width=\"2\" />\n          <text x=\"440\" y=\"40\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"14\" fill=\"#0284c7\"\n            text-anchor=\"middle\">NÍVEL EXTERNO (Visões dos Usuários / Aplicações)</text>\n\n          <rect x=\"70\" y=\"50\" width=\"220\" height=\"24\" rx=\"3\" fill=\"#ffffff\" stroke=\"#cbd5e1\" />\n          <text x=\"180\" y=\"66\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#334155\"\n            text-anchor=\"middle\">Visão Comercial (Vendas)</text>\n\n          <rect x=\"330\" y=\"50\" width=\"220\" height=\"24\" rx=\"3\" fill=\"#ffffff\" stroke=\"#cbd5e1\" />\n          <text x=\"440\" y=\"66\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#334155\"\n            text-anchor=\"middle\">Visão Financeira (Faturamento)</text>\n\n          <rect x=\"590\" y=\"50\" width=\"220\" height=\"24\" rx=\"3\" fill=\"#ffffff\" stroke=\"#cbd5e1\" />\n          <text x=\"700\" y=\"66\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#334155\"\n            text-anchor=\"middle\">Visão Recursos Humanos</text>\n\n          <!-- Seta Independência Lógica -->\n          <line x1=\"440\" y1=\"85\" x2=\"440\" y2=\"130\" stroke=\"#b20000\" stroke-width=\"2\" stroke-dasharray=\"4,4\" />\n          <polygon points=\"440,135 435,125 445,125\" fill=\"#b20000\" />\n          <text x=\"560\" y=\"112\" font-family=\"'Fira Code', monospace\" font-size=\"11\" fill=\"#b20000\">Independência Lógica\n            de Dados</text>\n\n          <!-- Nível Conceitual -->\n          <rect x=\"40\" y=\"140\" width=\"800\" height=\"70\" rx=\"4\" fill=\"#f8fafc\" stroke=\"#b20000\" stroke-width=\"2\" />\n          <text x=\"440\" y=\"165\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"14\" fill=\"#b20000\"\n            text-anchor=\"middle\">NÍVEL CONCEITUAL (Esquema Global da Organização)</text>\n          <text x=\"440\" y=\"190\" font-family=\"'Inter', sans-serif\" font-size=\"12\" fill=\"#334155\"\n            text-anchor=\"middle\">Entidades, Relacionamentos, Atributos e Regras Semânticas Gerais (Independente de\n            SGBD)</text>\n\n          <!-- Seta Independência Física -->\n          <line x1=\"440\" y1=\"210\" x2=\"440\" y2=\"255\" stroke=\"#15803d\" stroke-width=\"2\" stroke-dasharray=\"4,4\" />\n          <polygon points=\"440,260 435,250 445,250\" fill=\"#15803d\" />\n          <text x=\"560\" y=\"238\" font-family=\"'Fira Code', monospace\" font-size=\"11\" fill=\"#15803d\">Independência Física\n            de Dados</text>\n\n          <!-- Nível Interno -->\n          <rect x=\"40\" y=\"265\" width=\"800\" height=\"60\" rx=\"4\" fill=\"#f8fafc\" stroke=\"#15803d\" stroke-width=\"2\" />\n          <text x=\"440\" y=\"290\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"14\" fill=\"#15803d\"\n            text-anchor=\"middle\">NÍVEL INTERNO / FÍSICO (Armazenamento em Disco)</text>\n          <text x=\"440\" y=\"310\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#64748b\"\n            text-anchor=\"middle\">Organização de blocos em disco, índices (B-Tree, Hash), alocação de tabelas e\n            compressão</text>\n        </svg>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica</div>\n      <h2 class=\"slide-title\">Conceito de Independência de Dados</h2>\n      <p class=\"slide-subtitle\">A Loja Conecta pode criar um índice para acelerar a busca por pedido sem alterar a tela usada pelo atendimento.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Independência Lógica de Dados</div>\n          <p class=\"card-desc\">Capacidade de alterar o esquema conceitual (ex.: inclusão de uma nova entidade ou\n            atributo) sem a necessidade de modificar os programas de aplicação ou as visões externas existentes que não\n            utilizam os elementos alterados.</p>\n          <div class=\"code-box\" style=\"margin-top: 10px;\">\n            A inclusão de uma tabela de auditoria não altera as consultas do módulo de faturamento.\n          </div>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"card-title\">Independência Física de Dados</div>\n          <p class=\"card-desc\">Capacidade de reorganizar a estrutura física de armazenamento (ex.: criação de índices,\n            migração para novos dispositivos de armazenamento ou particionamento de tabelas) sem a necessidade de\n            modificar o esquema conceitual ou o código das consultas SQL.</p>\n          <div class=\"code-box\" style=\"margin-top: 10px;\">\n            A criação de um índice para otimização não exige alteração nas declarações SELECT dos sistemas.\n          </div>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fixação 1 &bull; 40 minutos</div>\n      <h2 class=\"slide-title\">Fundamentos de bancos de dados</h2>\n      <p class=\"slide-subtitle\">Responda individualmente ou em dupla. Envie uma foto ou arquivo pelo canal indicado no Teams.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">1. Dado, informação e metadado</div>\n          <p class=\"card-desc\">Use o valor <code>450,00</code> para criar um exemplo de dado e de informação. Depois, cite dois metadados necessários para armazená-lo.</p>\n        </div>\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">2. Tipologia dos dados</div>\n          <p class=\"card-desc\">Classifique cadastro de pacientes, laudo em JSON e imagem de tomografia como estruturado, semiestruturado ou não estruturado.</p>\n        </div>\n        <div class=\"card card-green\">\n          <div class=\"card-title\">3. Arquivos e SGBD</div>\n          <p class=\"card-desc\">Explique dois problemas de manter cadastros em planilhas separadas e como um SGBD ajuda a resolvê-los.</p>\n        </div>\n        <div class=\"card\">\n          <div class=\"card-title\">4. Independência de dados</div>\n          <p class=\"card-desc\">A troca do disco e a reorganização dos arquivos obrigam a alterar o sistema? Justifique com a arquitetura ANSI/SPARC.</p>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide slide-cover\">\n      <div class=\"section-tag\">Bloco 2 &bull; 60 minutos</div>\n      <h2 class=\"cover-title\" style=\"font-size: 2.6rem;\">Correção e modelagem conceitual</h2>\n      <p class=\"slide-subtitle\" style=\"max-width: 760px;\">15 minutos para discutir a Fixação 1 e 45 minutos para níveis de modelagem, MER, DER e o método de cinco etapas.</p>\n      <div class=\"callout\" style=\"max-width: 760px; text-align: left;\">\n        <strong>Pontos para a correção:</strong> contexto transforma dado em informação; tipos e regras são metadados;\n        um SGBD centraliza integridade; mudanças físicas não devem alterar as visões externas.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Infográfico Metodológico</div>\n      <h2 class=\"slide-title\">Ciclo de Modelagem: Conceitual, Lógico e Físico</h2>\n      <p class=\"slide-subtitle\">Para informatizar uma clínica, primeiro entendemos pacientes e consultas, depois definimos tabelas e, por fim, escolhemos tipos e índices do SGBD.</p>\n\n      <div class=\"diagram-container\">\n        <svg class=\"diagram-svg\" viewBox=\"0 0 900 330\" xmlns=\"http://www.w3.org/2000/svg\">\n          <!-- Coluna 1: Conceitual -->\n          <rect x=\"20\" y=\"30\" width=\"260\" height=\"280\" rx=\"6\" fill=\"#f8fafc\" stroke=\"#b20000\" stroke-width=\"2\" />\n          <rect x=\"20\" y=\"30\" width=\"260\" height=\"38\" rx=\"6\" fill=\"#b20000\" />\n          <text x=\"150\" y=\"55\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"#ffffff\"\n            text-anchor=\"middle\">1. MODELO CONCEITUAL</text>\n\n          <text x=\"150\" y=\"95\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"12\" fill=\"#1e293b\"\n            text-anchor=\"middle\">Visão Semântica do Negócio</text>\n          <text x=\"150\" y=\"115\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#64748b\"\n            text-anchor=\"middle\">Independe de tecnologia e de SGBD</text>\n\n          <rect x=\"60\" y=\"145\" width=\"80\" height=\"35\" rx=\"3\" fill=\"#ffffff\" stroke=\"#b20000\" />\n          <text x=\"100\" y=\"167\" font-family=\"'Inter', sans-serif\" font-size=\"10\" fill=\"#1e293b\"\n            text-anchor=\"middle\">CLIENTE</text>\n\n          <polygon points=\"200,162 175,148 175,176\" fill=\"#b20000\" />\n          <text x=\"210\" y=\"166\" font-family=\"'Inter', sans-serif\" font-size=\"10\" fill=\"#475569\">possui</text>\n\n          <text x=\"150\" y=\"240\" font-family=\"'Inter', sans-serif\" font-weight=\"600\" font-size=\"11\" fill=\"#b20000\"\n            text-anchor=\"middle\">Entidades &bull; Atributos &bull; Relacionamentos</text>\n          <text x=\"150\" y=\"260\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#64748b\"\n            text-anchor=\"middle\">Notação: DER (Chen ou Crow's Foot)</text>\n\n          <!-- Seta 1 -> 2 -->\n          <line x1=\"290\" y1=\"170\" x2=\"315\" y2=\"170\" stroke=\"#64748b\" stroke-width=\"2\" />\n          <polygon points=\"320,170 312,165 312,175\" fill=\"#64748b\" />\n\n          <!-- Coluna 2: Lógico -->\n          <rect x=\"320\" y=\"30\" width=\"260\" height=\"280\" rx=\"6\" fill=\"#f8fafc\" stroke=\"#0284c7\" stroke-width=\"2\" />\n          <rect x=\"320\" y=\"30\" width=\"260\" height=\"38\" rx=\"6\" fill=\"#0284c7\" />\n          <text x=\"450\" y=\"55\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"#ffffff\"\n            text-anchor=\"middle\">2. MODELO LÓGICO</text>\n\n          <text x=\"450\" y=\"95\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"12\" fill=\"#1e293b\"\n            text-anchor=\"middle\">Visão Estrutural Relacional</text>\n          <text x=\"450\" y=\"115\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#64748b\"\n            text-anchor=\"middle\">Aderente ao paradigma relacional</text>\n\n          <rect x=\"345\" y=\"140\" width=\"210\" height=\"65\" rx=\"3\" fill=\"#ffffff\" stroke=\"#0284c7\" />\n          <text x=\"450\" y=\"158\" font-family=\"'Fira Code', monospace\" font-size=\"10\" font-weight=\"600\" fill=\"#0284c7\"\n            text-anchor=\"middle\">CLIENTE</text>\n          <text x=\"355\" y=\"176\" font-family=\"'Fira Code', monospace\" font-size=\"9\" fill=\"#1e293b\">• id_cliente\n            (PK)</text>\n          <text x=\"355\" y=\"192\" font-family=\"'Fira Code', monospace\" font-size=\"9\" fill=\"#64748b\">• nome,\n            telefone</text>\n\n          <text x=\"450\" y=\"240\" font-family=\"'Inter', sans-serif\" font-weight=\"600\" font-size=\"11\" fill=\"#0284c7\"\n            text-anchor=\"middle\">Tabelas &bull; Chaves Primárias &bull; Estrangeiras</text>\n          <text x=\"450\" y=\"260\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#64748b\"\n            text-anchor=\"middle\">Esquema Relacional / Normalização</text>\n\n          <!-- Seta 2 -> 3 -->\n          <line x1=\"590\" y1=\"170\" x2=\"615\" y2=\"170\" stroke=\"#64748b\" stroke-width=\"2\" />\n          <polygon points=\"620,170 612,165 612,175\" fill=\"#64748b\" />\n\n          <!-- Coluna 3: Físico -->\n          <rect x=\"620\" y=\"30\" width=\"260\" height=\"280\" rx=\"6\" fill=\"#f8fafc\" stroke=\"#15803d\" stroke-width=\"2\" />\n          <rect x=\"620\" y=\"30\" width=\"260\" height=\"38\" rx=\"6\" fill=\"#15803d\" />\n          <text x=\"750\" y=\"55\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"#ffffff\"\n            text-anchor=\"middle\">3. MODELO FÍSICO</text>\n\n          <text x=\"750\" y=\"95\" font-family=\"'Inter', sans-serif\" font-weight=\"700\" font-size=\"12\" fill=\"#1e293b\"\n            text-anchor=\"middle\">Visão de Implementação</text>\n          <text x=\"750\" y=\"115\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#64748b\"\n            text-anchor=\"middle\">Específico para o SGBD adotado</text>\n\n          <rect x=\"640\" y=\"140\" width=\"220\" height=\"65\" rx=\"3\" fill=\"#ffffff\" stroke=\"#15803d\" />\n          <text x=\"650\" y=\"158\" font-family=\"'Fira Code', monospace\" font-size=\"9\" fill=\"#15803d\">CREATE TABLE cliente\n            (</text>\n          <text x=\"655\" y=\"174\" font-family=\"'Fira Code', monospace\" font-size=\"8\" fill=\"#475569\">id SERIAL PRIMARY\n            KEY,</text>\n          <text x=\"655\" y=\"190\" font-family=\"'Fira Code', monospace\" font-size=\"8\" fill=\"#475569\">nome VARCHAR(100) NOT\n            NULL);</text>\n\n          <text x=\"750\" y=\"240\" font-family=\"'Inter', sans-serif\" font-weight=\"600\" font-size=\"11\" fill=\"#15803d\"\n            text-anchor=\"middle\">Scripts DDL &bull; Tipos Concretos &bull; Índices</text>\n          <text x=\"750\" y=\"260\" font-family=\"'Inter', sans-serif\" font-size=\"11\" fill=\"#64748b\"\n            text-anchor=\"middle\">PostgreSQL, MySQL, Oracle, etc.</text>\n        </svg>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica</div>\n      <h2 class=\"slide-title\">Comparativo Formal: Conceitual vs. Lógico vs. Físico</h2>\n      <p class=\"slide-subtitle\">A regra “um aluno realiza várias matrículas” aparece como relacionamento no conceito, como chaves no modelo lógico e como colunas SQL no físico.</p>\n\n      <div class=\"table-container\">\n        <table class=\"modern-table\">\n          <thead>\n            <tr>\n              <th>Critério</th>\n              <th>Modelo Conceitual</th>\n              <th>Modelo Lógico</th>\n              <th>Modelo Físico</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td><strong>Nível de Abstração</strong></td>\n              <td>Alto (Visão de Negócio)</td>\n              <td>Intermediário (Visão Estrutural)</td>\n              <td>Baixo (Visão Tecnológica)</td>\n            </tr>\n            <tr>\n              <td><strong>Público-Alvo</strong></td>\n              <td>Analistas de Negócio e Usuários Finais</td>\n              <td>Analistas de Sistemas e Projetistas</td>\n              <td>DBAs e Engenheiros de Dados</td>\n            </tr>\n            <tr>\n              <td><strong>Dependência de Software</strong></td>\n              <td>Independente de SGBD e de tecnologia</td>\n              <td>Dependente do paradigma (ex.: Relacional)</td>\n              <td>Específico de um SGBD concreto</td>\n            </tr>\n            <tr>\n              <td><strong>Componentes Centrais</strong></td>\n              <td>Entidades, Atributos e Relacionamentos</td>\n              <td>Tabelas, Colunas, Chaves PK e FK</td>\n              <td>Tipos (`INT`, `VARCHAR`), Índices e DDL</td>\n            </tr>\n            <tr>\n              <td><strong>Artefato de Saída</strong></td>\n              <td>Diagrama Entidade-Relacionamento (DER)</td>\n              <td>Esquema Relacional Tabular</td>\n              <td>Script SQL DDL (`CREATE TABLE`)</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fundamentação Teórica</div>\n      <h2 class=\"slide-title\">Diferença Formal entre MER e DER</h2>\n      <p class=\"slide-subtitle\">Assim como a organização dos cômodos é uma ideia do projeto e a planta é o desenho dessa ideia, MER e DER cumprem papéis diferentes.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">MER — Modelo Entidade-Relacionamento</div>\n          <div class=\"badge badge-red\" style=\"margin-bottom: 10px;\">Conceito / Modelo Teórico</div>\n          <p class=\"card-desc\">Proposto por <strong>Peter Chen em 1976</strong>. É a formulação semântica e abstrata das\n            entidades, seus atributos, relacionamentos e restrições de integridade.</p>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.82rem;\">\n            O MER define a estrutura e semântica dos dados independentemente de representação gráfica.\n          </div>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">DER — Diagrama Entidade-Relacionamento</div>\n          <div class=\"badge badge-blue\" style=\"margin-bottom: 10px;\">Representação Gráfica</div>\n          <p class=\"card-desc\">É a notação diagramática que esquematiza visualmente os componentes do MER utilizando\n            símbolos padronizados (retângulos, elipses, losangos ou pé-de-galinha).</p>\n          <div class=\"code-box\" style=\"margin-top: 10px; font-size: 0.82rem;\">\n            O DER é o desenho gráfico que documenta e comunica visualmente o MER.\n          </div>\n        </div>\n      </div>\n\n      <div class=\"callout\" style=\"margin-top: 16px;\">\n        <strong>Rigor Terminológico:</strong> O MER é a especificação formal do modelo; o DER é a sua representação\n        gráfica. Documenta-se o modelo por meio de diagramas.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Metodologia Prática</div>\n      <h2 class=\"slide-title\">Modelagem Inicial sem Recursos Computacionais</h2>\n      <p class=\"slide-subtitle\">Antes de abrir o PostgreSQL, uma equipe costuma rascunhar quem é cadastrado, quais regras precisam valer e como os elementos se relacionam.</p>\n\n      <div class=\"card card-red\" style=\"padding: 24px;\">\n        <p style=\"font-size: 1.05rem; line-height: 1.7; color: var(--cps-gray-dark);\">\n          <strong>Objetivo Pedagógico:</strong> A concepção de um esquema de dados exige raciocínio analítico sobre os\n          requisitos de negócio e a identificação precisa das relações entre os elementos.\n        </p>\n        <p style=\"font-size: 0.95rem; line-height: 1.7; color: var(--cps-gray-medium); margin-top: 12px;\">\n          Nesta etapa inicial, afastar-se do teclado e do software evita o desvio de atenção para detalhes de sintaxe\n          SQL, tipos de dados proprietários ou interfaces de ferramentas. O foco concentra-se exclusivamente na\n          semântica, integridade e cardinalidades mínimas e máximas.\n        </p>\n      </div>\n\n      <div class=\"grid-3\" style=\"margin-top: 18px;\">\n        <div class=\"card\" style=\"padding: 14px;\">\n          <strong style=\"color: var(--cps-red);\">1. Foco Semântico</strong>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 4px;\">Compreensão das regras de negócio sem\n            interferência de comandos de SGBD.</p>\n        </div>\n        <div class=\"card\" style=\"padding: 14px;\">\n          <strong style=\"color: var(--tech-blue);\">2. Raciocínio Estruturado</strong>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 4px;\">Validação de cardinalidades (1,1), (1,N) e\n            (N,N) diretamente no papel.</p>\n        </div>\n        <div class=\"card\" style=\"padding: 14px;\">\n          <strong style=\"color: var(--tech-green);\">3. Transição Segura</strong>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 4px;\">Um DER correto no papel viabiliza a geração\n            de esquemas lógicos e físicos sem retrabalho.</p>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Metodologia Prática</div>\n      <h2 class=\"slide-title\">Etapas da Modelagem Conceitual</h2>\n      <p class=\"slide-subtitle\">Partiremos de um pedido comum, como “a clínica precisa controlar clientes e pets”, até produzir um diagrama que qualquer integrante da equipe possa revisar.</p>\n\n      <div class=\"stepper\">\n        <div class=\"step-item\">\n          <div class=\"step-circle\">1</div>\n          <div class=\"step-title\">Texto Narrativo</div>\n          <div class=\"step-desc\">Requisitos do cliente</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">2</div>\n          <div class=\"step-title\">Identificação</div>\n          <div class=\"step-desc\">Entidades e atributos</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">3</div>\n          <div class=\"step-title\">Regras de Negócio</div>\n          <div class=\"step-desc\">Cardinalidades min e max</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">4</div>\n          <div class=\"step-title\">Modelo Conceitual</div>\n          <div class=\"step-desc\">Estruturação (MER)</div>\n        </div>\n        <div class=\"step-item\">\n          <div class=\"step-circle\">5</div>\n          <div class=\"step-title\">DER Gráfico</div>\n          <div class=\"step-desc\">Diagramação visual</div>\n        </div>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 20px;\">\n        <strong>Diretriz:</strong> Cada etapa fornece insumos diretos para a subsequente, garantindo a rastreabilidade\n        entre as regras de negócio declaradas e o diagrama resultante.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Metodologia Prática</div>\n      <h2 class=\"slide-title\">Mapeamento Gramatical de Requisitos</h2>\n      <p class=\"slide-subtitle\">Na frase “um cliente possui vários pets”, os substantivos sugerem entidades, o verbo indica a relação e “vários” ajuda a definir a cardinalidade.</p>\n\n      <div class=\"grid-3\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Substantivos</div>\n          <p class=\"card-desc\">Substantivos identificam candidatos a <strong>Entidades</strong> (objetos de interesse)\n            ou <strong>Atributos</strong> (propriedades descritivas).</p>\n          <div class=\"code-box\" style=\"margin-top: 8px; font-size: 0.8rem;\">\n            \"Cliente\", \"Pet\", \"Nome\", \"Código\"\n          </div>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Verbos</div>\n          <p class=\"card-desc\">Verbos de ligação ou ação indicam associações semânticas, correspondendo aos\n            <strong>Relacionamentos</strong>.\n          </p>\n          <div class=\"code-box\" style=\"margin-top: 8px; font-size: 0.8rem;\">\n            \"possui\", \"realiza\", \"ministra\", \"publica\"\n          </div>\n        </div>\n\n        <div class=\"card card-green\">\n          <div class=\"card-title\">Quantificadores</div>\n          <p class=\"card-desc\">Expressões quantitativas e restrições de obrigatoriedade determinam as\n            <strong>Cardinalidades</strong> mínimas e máximas.\n          </p>\n          <div class=\"code-box\" style=\"margin-top: 8px; font-size: 0.8rem;\">\n            \"exatamente um\", \"um ou vários\", \"opcional\"\n          </div>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Bloco 2 &bull; Exemplo guiado</div>\n      <h2 class=\"slide-title\">Estudo de Caso Guiado: Clínica Veterinária \"PetCare\"</h2>\n      <p class=\"slide-subtitle\">Etapa 1: Leitura e análise dos requisitos expressos em linguagem natural.</p>\n\n      <div class=\"card card-red\" style=\"padding: 22px; font-size: 1.05rem; line-height: 1.8;\">\n        <p>\n          <em>\"A clínica veterinária <strong>PetCare</strong> necessita de um sistema para controle de atendimentos. O\n            sistema deve cadastrar os <strong>clientes</strong>, mantendo o <strong>código</strong>, o\n            <strong>nome</strong> completo e o <strong>telefone</strong> de cada um.</em>\n        </p>\n        <p style=\"margin-top: 10px;\">\n          <em>Cada cliente pode possuir um ou vários <strong>pets</strong> (animais). De cada pet, devem ser armazenados\n            o <strong>código</strong> de registro, o <strong>nome</strong> e a <strong>espécie</strong> (cão, gato,\n            etc.).</em>\n        </p>\n        <p style=\"margin-top: 10px;\">\n          <em>Regra da clínica: todo pet cadastrado deve estar associado obrigatoriamente a exatamente um cliente.\"</em>\n        </p>\n      </div>\n\n      <div class=\"callout callout-blue\" style=\"margin-top: 18px;\">\n        <strong>Atividade:</strong> desenvolveremos juntos, por compartilhamento de tela, as etapas 2, 3, 4 e 5.\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Bloco 2 &bull; Exemplo guiado</div>\n      <h2 class=\"slide-title\">Etapas 2 e 3: Elementos e Regras de Negócio</h2>\n      <p class=\"slide-subtitle\">Identificação analítica dos componentes e mapeamento das cardinalidades.</p>\n\n      <div class=\"grid-2\">\n        <div class=\"card card-red\">\n          <div class=\"card-title\">Etapa 2: Identificação dos Elementos</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.9rem; line-height: 1.8; padding-left: 18px;\">\n            <li><strong>Entidades:</strong> <code>CLIENTE</code> e <code>PET</code>.</li>\n            <li><strong>Atributos de CLIENTE:</strong> <span style=\"color: var(--cps-red); font-weight: 600;\">id_cliente\n                (identificador)</span>, nome, telefone.</li>\n            <li><strong>Atributos de PET:</strong> <span style=\"color: var(--cps-red); font-weight: 600;\">id_pet\n                (identificador)</span>, nome, espécie.</li>\n            <li><strong>Relacionamento:</strong> <code>POSSUI</code>.</li>\n          </ul>\n        </div>\n\n        <div class=\"card card-blue\">\n          <div class=\"card-title\">Etapa 3: Regras e Cardinalidades</div>\n          <ul style=\"color: var(--cps-gray-medium); font-size: 0.9rem; line-height: 1.8; padding-left: 18px;\">\n            <li><strong>CLIENTE para PET:</strong> Um cliente pode ter no mínimo 1 e no máximo muitos pets &rarr;\n              <strong>(1, N)</strong>.\n            </li>\n            <li><strong>PET para CLIENTE:</strong> Cada pet pertence obrigatoriamente a exatamente 1 cliente &rarr;\n              <strong>(1, 1)</strong>.\n            </li>\n            <li><strong>Classificação:</strong> Relacionamento binário de cardinalidade máxima <strong>1 para N\n                (1:N)</strong>.</li>\n          </ul>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Bloco 2 &bull; Exemplo guiado</div>\n      <h2 class=\"slide-title\">Etapas 4 e 5: DER Conceitual Completo (Notação Chen)</h2>\n      <p class=\"slide-subtitle\">Representação gráfica padronizada da modelagem conceitual.</p>\n\n      <div class=\"diagram-container\">\n        <img src=\"../Banco de Dados I/slides/img/der_pet.png\" alt=\"DER Notação Chen — Estudo de Caso Clínica PetCare\" class=\"diagram-img\">\n      </div>\n    </section>",
  "<section class=\"slide\">\n      <div class=\"section-tag\">Fixação 2 &bull; 40 minutos</div>\n      <h2 class=\"slide-title\">Biblioteca Saber</h2>\n      <p class=\"slide-subtitle\">Atividade individual iniciada no Teams e corrigida na próxima aula presencial.</p>\n\n      <div class=\"card card-red\" style=\"padding: 22px; font-size: 1.05rem; line-height: 1.8;\">\n        <p>\n          <em>\"A Biblioteca Municipal <strong>Saber</strong> deseja informatizar o catálogo de livros. Cada\n            <strong>livro</strong> possui um <strong>código</strong> identificador, o <strong>título</strong> da obra e\n            o <strong>ano de publicação</strong>.</em>\n        </p>\n        <p style=\"margin-top: 10px;\">\n          <em>Cada livro é publicado por exatamente uma <strong>editora</strong>. De cada editora, são registrados o\n            <strong>código</strong> de identificação, a <strong>razão social</strong> e a <strong>cidade</strong> sede.\n            Uma editora pode publicar múltiplos livros cadastrados no acervo da biblioteca.\"</em>\n        </p>\n      </div>\n\n      <div class=\"grid-3\" style=\"margin-top: 18px;\">\n        <div class=\"card\" style=\"padding: 14px;\">\n          <strong style=\"color: var(--cps-red);\">Etapa 2: Identificação</strong>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 4px;\">Identifique entidades, atributos\n            identificadores e atributos descritivos.</p>\n        </div>\n        <div class=\"card\" style=\"padding: 14px;\">\n          <strong style=\"color: var(--tech-blue);\">Etapa 3: Cardinalidades</strong>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 4px;\">Defina os limites mínimos e máximos de\n            publicação entre Livro e Editora.</p>\n        </div>\n        <div class=\"card\" style=\"padding: 14px;\">\n          <strong style=\"color: var(--tech-green);\">Etapas 4 e 5: Diagramação</strong>\n          <p class=\"card-desc\" style=\"font-size: 0.82rem; margin-top: 4px;\">Desenhe o DER na notação Chen com todos os\n            símbolos e conexões.</p>\n        </div>\n      </div>\n    </section>",
  "<section class=\"slide slide-cover\">\n      <div class=\"section-tag\">Encerramento &bull; Próximos Passos</div>\n      <h2 class=\"cover-title\" style=\"font-size: 2.6rem;\">Síntese da Aula 01</h2>\n      <p class=\"slide-subtitle\" style=\"max-width: 720px; margin-bottom: 24px;\">\n        Consolidação dos fundamentos teóricos de persistência, níveis de abstração e início do ciclo de modelagem\n        conceitual.\n      </p>\n\n      <div class=\"card card-red\" style=\"max-width: 680px; text-align: left; margin: 0 auto 24px auto;\">\n        <div class=\"card-title\">Próxima aula presencial:</div>\n        <ul style=\"color: var(--cps-gray-medium); font-size: 0.9rem; line-height: 1.8; padding-left: 18px;\">\n          <li>Correção comentada do DER da Biblioteca Saber.</li>\n          <li>Tipologia de atributos (compostos, multivalorados, derivados e identificadores).</li>\n          <li>Entidades Fortes e Entidades Fracas (dependência existencial e de identificação).</li>\n          <li>Início da utilização prática do software de modelagem <strong>brModelo</strong> em laboratório.</li>\n        </ul>\n      </div>\n\n      <div style=\"color: var(--cps-gray-medium); font-size: 0.85rem;\">\n        Faculdade de Tecnologia de Sorocaba — Fatec Sorocaba &bull; Centro Paula Souza\n      </div>\n    </section>"
]
};
